const body = $input.first().json;
const type = body.type;

let toEmail = '';
let subject = '';
let html = '';

if (type === 'user_registration') {
  toEmail = body.email;
  subject = 'Welcome to ClubHub!';
  html = `<h2>Hi ${body.name},</h2><p>Welcome to ClubHub! Your account has been created successfully as a <strong>${body.role}</strong>.</p><p>Login to explore clubs and events.</p><br><p>Team ClubHub</p>`;

} else if (type === 'FORGOT_PASSWORD') {
  toEmail = body.email;
  subject = 'Reset Your Password - ClubHub';
  html = `<h2>Hi ${body.name},</h2><p>Click the button below to reset your password. This link expires in 15 minutes.</p><p><a href="${body.resetLink}" style="background:#1e3a5f;color:white;padding:10px 20px;border-radius:5px;text-decoration:none;">Reset Password</a></p><br><p>If you did not request this, ignore this email.</p>`;

} else if (type === 'leader_appointed') {
  toEmail = body.email;
  subject = `You are now Leader of ${body.clubName} - ClubHub`;
  html = `<h2>Congratulations ${body.name}!</h2><p>You have been appointed as the leader of <strong>${body.clubName}</strong> on ClubHub.</p><p>Login to manage your club, approve members, and create events.</p><br><p>Team ClubHub</p>`;

} else if (type === 'membership_approved') {
  toEmail = body.email;
  subject = `Membership Approved - ${body.clubName}`;
  html = `<h2>Hi ${body.name},</h2><p>Your request to join <strong>${body.clubName}</strong> has been approved!</p><p>Login to ClubHub to see upcoming events from your club.</p><br><p>Team ClubHub</p>`;

} else if (type === 'event_approved') {
  toEmail = body.leaderEmail;
  subject = `Your Event "${body.eventTitle}" is Approved!`;
  html = `<h2>Hi ${body.leaderName},</h2><p>Great news! Your event <strong>${body.eventTitle}</strong> has been approved by the admin.</p><p><strong>Date:</strong> ${new Date(body.eventDate).toLocaleDateString('en-IN')}<br><strong>Venue:</strong> ${body.venue}</p><p>Students can now register for your event.</p><br><p>Team ClubHub</p>`;

} else if (type === 'event_rejected') {
  toEmail = body.leaderEmail;
  subject = `Your Event "${body.eventTitle}" was Rejected`;
  html = `<h2>Hi ${body.leaderName},</h2><p>Unfortunately, your event <strong>${body.eventTitle}</strong> has been rejected.</p>${body.rejectionReason ? `<p><strong>Reason:</strong> ${body.rejectionReason}</p>` : ''}<p>You can update and resubmit the event for review.</p><br><p>Team ClubHub</p>`;

} else if (type === 'event_registered') {
  toEmail = body.studentEmail;
  subject = `Registration Confirmed - ${body.eventTitle}`;
  html = `<h2>Hi ${body.studentName},</h2><p>You have successfully registered for <strong>${body.eventTitle}</strong>!</p><p><strong>Date:</strong> ${new Date(body.eventDate).toLocaleDateString('en-IN')}<br><strong>Venue:</strong> ${body.venue}</p>${body.qrCodeUrl ? `<p>Your QR ticket: <a href="${body.qrCodeUrl}">View QR Code</a></p>` : ''}<br><p>Team ClubHub</p>`;

} else if (type === 'payment_success') {
  toEmail = body.studentEmail;
  subject = `Payment Confirmed - ${body.eventTitle}`;
  html = `<h2>Hi ${body.studentName},</h2><p>Your payment of <strong>&#8377;${body.amount}</strong> for <strong>${body.eventTitle}</strong> was successful!</p><p><strong>Payment ID:</strong> ${body.paymentId}</p>${body.qrCodeUrl ? `<p>Your QR ticket: <a href="${body.qrCodeUrl}">View QR Code</a></p>` : ''}<br><p>Team ClubHub</p>`;

} else if (type === 'attendance_marked') {
  toEmail = body.studentEmail;
  subject = `Attendance Marked - ${body.eventTitle}`;
  html = `<h2>Hi ${body.studentName},</h2><p>Your attendance for <strong>${body.eventTitle}</strong> by <strong>${body.clubName}</strong> has been successfully recorded.</p><p>You can now download your participation certificate from My Events.</p><br><p>Team ClubHub</p>`;
}

return [{ json: { toEmail, subject, html } }];
